import sys
from itertools import product

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    n = int(next(iterator))
    m = int(next(iterator))

    rows_count = []
    for _ in range(n):
        rows_count.append(int(next(iterator)))

    cols_count = []
    for _ in range(m):
        cols_count.append(int(next(iterator)))

    # Generate all possible binary strings of length m
    # Since m <= 20, 2^20 is ~1 million, which is acceptable
    # But we need to filter by row constraints first to reduce search space

    def count_segments(s):
        cnt = 0
        prev = False
        for c in s:
            curr = (c == '*')
            if curr and not prev:
                cnt += 1
            prev = curr
        return cnt

    # Precompute valid row configurations
    valid_rows = []
    for r_idx in range(n):
        target = rows_count[r_idx]
        valid_configs = []
        # Iterate through all 2^m possibilities
        for bits in range(1 << m):
            s = []
            for j in range(m):
                if (bits >> (m - 1 - j)) & 1:
                    s.append('*')
                else:
                    s.append('.')
            segs = count_segments("".join(s))
            if segs == target:
                valid_configs.append("".join(s))
        valid_rows.append(valid_configs)

    # Now use backtracking to select one configuration per row
    # such that column constraints are satisfied

    solution = None

    def backtrack(row_idx, current_grid):
        nonlocal solution
        if solution is not None:
            return True

        if row_idx == n:
            # Check column constraints
            for c_idx in range(m):
                col_str = "".join(current_grid[r][c_idx] for r in range(n))
                if count_segments(col_str) != cols_count[c_idx]:
                    return False
            solution = current_grid
            return True

        for config in valid_rows[row_idx]:
            new_grid = current_grid + [config]
            # Optimization: check partial column constraints?
            # Given n is small (<=5), full check at end is fast enough
            if backtrack(row_idx + 1, new_grid):
                return True

        return False

    backtrack(0, [])

    if solution:
        for line in solution:
            print(line)

if __name__ == "__main__":
    solve()
